class Solution {
    struct Interval {
        int l, r, w, id;
    };
    int n;
    vector<Interval> arr;
    vector<int> starts;
    pair<long long, vector<int>> memo[50005][5];
    bool visited[50005][5];

    pair<long long, vector<int>> solve(int i, int k) {
        if (k == 0 || i == n) return {0LL, {}};
        if (visited[i][k]) return memo[i][k];

        auto skip = solve(i + 1, k);
        int nextIdx = upper_bound(starts.begin(), starts.end(), arr[i].r) - starts.begin();
        auto take = solve(nextIdx, k - 1);
        take.first += arr[i].w;
        take.second.push_back(arr[i].id);
        sort(take.second.begin(), take.second.end());

        pair<long long, vector<int>> res;
        if (take.first > skip.first) {
            res = take;
        } else if (take.first < skip.first) {
            res = skip;
        } else {
            res = {take.first, min(take.second, skip.second)};
        }
        visited[i][k] = true;
        return memo[i][k] = res;
    }

public:
    vector<int> maximumWeight(vector<vector<int>>& intervals) {
        n = intervals.size();
        arr.resize(n);
        for (int i = 0; i < n; ++i) {
            arr[i] = {intervals[i][0], intervals[i][1], intervals[i][2], i};
        }
        sort(arr.begin(), arr.end(), [](const auto& a, const auto& b) {
            return a.l < b.l;
        });
        starts.resize(n);
        for (int i = 0; i < n; ++i) starts[i] = arr[i].l;
        for (int i = 0; i <= n; ++i) {
            for (int k = 0; k <= 4; ++k) visited[i][k] = false;
        }

        auto ans = solve(0, 4);
        sort(ans.second.begin(), ans.second.end());
        return ans.second;
    }
