class Solution {
    static class Interval {
        int l, r, w, id;
        Interval(int l, int r, int w, int id) {
            this.l = l; this.r = r; this.w = w; this.id = id;
        }
    }

    static class State {
        long weight;
        List<Integer> indices;
        State(long weight, List<Integer> indices) {
            this.weight = weight;
            this.indices = indices;
        }
    }

    private int n;
    private Interval[] arr;
    private int[] starts;
    private State[][] memo;

    public int[] maximumWeight(int[][] intervals) {
        n = intervals.length;
        arr = new Interval[n];
        for (int i = 0; i < n; ++i) {
            arr[i] = new Interval(intervals[i][0], intervals[i][1], intervals[i][2], i);
        }
        Arrays.sort(arr, (a, b) -> Integer.compare(a.l, b.l));
        starts = new int[n];
        for (int i = 0; i < n; ++i) starts[i] = arr[i].l;
        memo = new State[n][5];

        State res = solve(0, 4);
        int[] ans = new int[res.indices.size()];
        for (int i = 0; i < ans.length; ++i) ans[i] = res.indices.get(i);
        Arrays.sort(ans);
        return ans;
    }

    private State solve(int i, int k) {
        if (k == 0 || i == n) return new State(0, new ArrayList<>());
        if (memo[i][k] != null) return memo[i][k];

        State skip = solve(i + 1, k);
        int nextIdx = upper_bound(starts, arr[i].r);
        State takeRaw = solve(nextIdx, k - 1);
        long takeW = takeRaw.weight + arr[i].w;
        List<Integer> takeIdx = new ArrayList<>(takeRaw.indices);
        takeIdx.add(arr[i].id);
        Collections.sort(takeIdx);

        State res;
        if (takeW > skip.weight) {
            res = new State(takeW, takeIdx);
        } else if (takeW < skip.weight) {
            res = skip;
        } else {
            res = new State(takeW, compareIndices(takeIdx, skip.indices) < 0 ? takeIdx : skip.indices);
        }
        return memo[i][k] = res;
    }

    private int upper_bound(int[] a, int target) {
        int l = 0, r = a.length;
        while (l < r) {
            int mid = (l + r) / 2;
            if (a[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    private int compareIndices(List<Integer> a, List<Integer> b) {
        int len = Math.min(a.size(), b.size());
        for (int i = 0; i < len; ++i) {
            int cmp = Integer.compare(a.get(i), b.get(i));
            if (cmp != 0) return cmp;
        }
        return Integer.compare(a.size(), b.size());
    }
}

var maximumWeight = function(intervals) {
    const n = intervals.length;
    const arr = intervals.map(([l, r, w], i) => ({ l, r, w, id: i }));
    arr.sort((a, b) => a.l - b.l);
    const starts = arr.map(x => x.l);
    const memo = new Map();

    function upper_bound(target) {
        let l = 0, r = starts.length;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (starts[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    function solve(i, k) {
        if (k === 0 || i === n) return { w: 0n, idx: [] };
        const key = (i << 3) | k;
        if (memo.has(key)) return memo.get(key);

        const skip = solve(i + 1, k);
        const nextIdx = upper_bound(arr[i].r);
        const takeRaw = solve(nextIdx, k - 1);
        const takeW = takeRaw.w + BigInt(arr[i].w);
        const takeIdx = [...takeRaw.idx, arr[i].id].sort((a, b) => a - b);

        let res;
        if (takeW > skip.w) {
            res = { w: takeW, idx: takeIdx };
        } else if (takeW < skip.w) {
            res = skip;
        } else {
            let pickTake = true;
            const minLen = Math.min(takeIdx.length, skip.idx.length);
            for (let p = 0; p < minLen; ++p) {
                if (takeIdx[p] !== skip.idx[p]) {
                    pickTake = takeIdx[p] < skip.idx[p];
                    break;
                }
            }
            res = { w: takeW, idx: pickTake ? takeIdx : skip.idx };
        }
        memo.set(key, res);
        return res;
    }

    const ans = solve(0, 4);
    return ans.idx.sort((a, b) => a - b);
};
